import argparse
import json

TIERS = {'e1': 'P1', 'e2': 'P2', 'e3': 'P2', 'e4': 'P3', 'e5': 'P1', 'e6': 'P2', 'e7': 'P3', 'e8': 'P1'}


def simulate_post(model, epic):
    """Fixed tiers per epic id, with one deliberate disagreement."""
    if model == 'candidate' and epic == 'e3':
        return 'P3'
    return TIERS[epic]


def live_post(model, epic):
    raise NotImplementedError('no non-telemetry scoring path yet')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--simulate', action='store_true')
    args = ap.parse_args()
    post = simulate_post if args.simulate else live_post
    agree = sum(post('incumbent', e) == post('candidate', e) for e in TIERS)
    print(json.dumps({'agreement': agree / len(TIERS)}))


if __name__ == '__main__':
    main()

